CREATE TYPE "DriverCategory" AS ENUM ('REGULAR','SUPPORT');
CREATE TYPE "TripStatus" AS ENUM ('PLANNED','ACTIVE','FINISHED');
CREATE TYPE "CommercialReturnStatus" AS ENUM ('AWAITING_RETURN','INSPECTION_REQUIRED','RESOLVED');
CREATE TABLE "TransferSchedule" ("id" TEXT NOT NULL,"transferId" TEXT NOT NULL,"orderId" TEXT NOT NULL,"departureAt" TIMESTAMP(3) NOT NULL,"expectedArrivalAt" TIMESTAMP(3) NOT NULL,"reason" TEXT NOT NULL,"recordedBy" TEXT NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TransferSchedule_pkey" PRIMARY KEY ("id"));
CREATE INDEX "TransferSchedule_transferId_recordedAt_idx" ON "TransferSchedule"("transferId","recordedAt");
ALTER TABLE "TransferSchedule" ADD CONSTRAINT "TransferSchedule_transferId_fkey" FOREIGN KEY ("transferId") REFERENCES "Transfer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TransferSchedule" ADD CONSTRAINT "TransferSchedule_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CustomerOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "DriverProfile" ("id" TEXT NOT NULL,"fullName" TEXT NOT NULL,"category" "DriverCategory" NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"available" BOOLEAN NOT NULL DEFAULT true,"authorizedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DriverProfile_pkey" PRIMARY KEY ("id"));
CREATE INDEX "DriverProfile_enabled_available_idx" ON "DriverProfile"("enabled","available");
CREATE TABLE "Trip" ("id" TEXT NOT NULL,"transferId" TEXT,"orderId" TEXT,"plannedDepartureAt" TIMESTAMP(3) NOT NULL,"plannedArrivalAt" TIMESTAMP(3),"status" "TripStatus" NOT NULL DEFAULT 'PLANNED',"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3),"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Trip_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Trip_transferId_createdAt_idx" ON "Trip"("transferId","createdAt");
CREATE INDEX "Trip_orderId_createdAt_idx" ON "Trip"("orderId","createdAt");
ALTER TABLE "Trip" ADD CONSTRAINT "Trip_transferId_fkey" FOREIGN KEY ("transferId") REFERENCES "Transfer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Trip" ADD CONSTRAINT "Trip_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CustomerOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "DriverAssignment" ("id" TEXT NOT NULL,"tripId" TEXT NOT NULL,"driverId" TEXT NOT NULL,"provisional" BOOLEAN NOT NULL DEFAULT false,"validUntil" TIMESTAMP(3),"reason" TEXT NOT NULL,"assignedBy" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DriverAssignment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "DriverAssignment_tripId_assignedAt_idx" ON "DriverAssignment"("tripId","assignedAt");
CREATE INDEX "DriverAssignment_driverId_assignedAt_idx" ON "DriverAssignment"("driverId","assignedAt");
ALTER TABLE "DriverAssignment" ADD CONSTRAINT "DriverAssignment_tripId_fkey" FOREIGN KEY ("tripId") REFERENCES "Trip"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DriverAssignment" ADD CONSTRAINT "DriverAssignment_driverId_fkey" FOREIGN KEY ("driverId") REFERENCES "DriverProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Dispatch" ADD COLUMN "tripId" TEXT;
ALTER TABLE "Dispatch" ADD CONSTRAINT "Dispatch_tripId_fkey" FOREIGN KEY ("tripId") REFERENCES "Trip"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "MeasuredDispatch" ADD COLUMN "tripId" TEXT;
ALTER TABLE "MeasuredDispatch" ADD CONSTRAINT "MeasuredDispatch_tripId_fkey" FOREIGN KEY ("tripId") REFERENCES "Trip"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ClientShipment" ADD COLUMN "tripId" TEXT;
ALTER TABLE "ClientShipment" ADD CONSTRAINT "ClientShipment_tripId_fkey" FOREIGN KEY ("tripId") REFERENCES "Trip"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "WeightOrderLine" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"plannedKg" DECIMAL(18,3) NOT NULL,"estimatedBoxes" INTEGER,"averageBoxKg" DECIMAL(18,3),"reservedKg" DECIMAL(18,3) NOT NULL DEFAULT 0,"dispatchedKg" DECIMAL(18,3) NOT NULL DEFAULT 0,CONSTRAINT "WeightOrderLine_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WeightOrderLine_orderId_productId_key" ON "WeightOrderLine"("orderId","productId");
ALTER TABLE "WeightOrderLine" ADD CONSTRAINT "WeightOrderLine_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CustomerOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "WeightOrderLine" ADD CONSTRAINT "WeightOrderLine_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "WeightShipment" ("id" TEXT NOT NULL,"weightLineId" TEXT NOT NULL,"nominalKg" DECIMAL(18,3) NOT NULL,"actualKg" DECIMAL(18,3) NOT NULL,"differenceKg" DECIMAL(18,3) NOT NULL,"documentRef" TEXT,"accountingRef" TEXT NOT NULL,"custodian" TEXT NOT NULL,"dispatchedBy" TEXT NOT NULL,"dispatchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WeightShipment_pkey" PRIMARY KEY ("id"));
ALTER TABLE "WeightShipment" ADD CONSTRAINT "WeightShipment_weightLineId_fkey" FOREIGN KEY ("weightLineId") REFERENCES "WeightOrderLine"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "CommercialReturn" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"returnLocationId" TEXT NOT NULL,"clientReceptionLineId" TEXT,"weightShipmentId" TEXT,"unit" "InventoryBaseUnit" NOT NULL,"expected" DECIMAL(18,3) NOT NULL,"status" "CommercialReturnStatus" NOT NULL DEFAULT 'AWAITING_RETURN',"reason" TEXT NOT NULL,"registeredBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedAt" TIMESTAMP(3),"resolvedBy" TEXT,CONSTRAINT "CommercialReturn_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommercialReturn_clientReceptionLineId_key" ON "CommercialReturn"("clientReceptionLineId");
CREATE UNIQUE INDEX "CommercialReturn_weightShipmentId_key" ON "CommercialReturn"("weightShipmentId");
CREATE INDEX "CommercialReturn_orderId_status_idx" ON "CommercialReturn"("orderId","status");
ALTER TABLE "CommercialReturn" ADD CONSTRAINT "CommercialReturn_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CustomerOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CommercialReturn" ADD CONSTRAINT "CommercialReturn_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CommercialReturn" ADD CONSTRAINT "CommercialReturn_returnLocationId_fkey" FOREIGN KEY ("returnLocationId") REFERENCES "Location"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CommercialReturn" ADD CONSTRAINT "CommercialReturn_clientReceptionLineId_fkey" FOREIGN KEY ("clientReceptionLineId") REFERENCES "ClientReceptionLine"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CommercialReturn" ADD CONSTRAINT "CommercialReturn_weightShipmentId_fkey" FOREIGN KEY ("weightShipmentId") REFERENCES "WeightShipment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "ReturnIntake" ("id" TEXT NOT NULL,"returnId" TEXT NOT NULL,"observed" DECIMAL(18,3) NOT NULL,"conditionNote" TEXT NOT NULL,"evidenceRef" TEXT,"observedAt" TIMESTAMP(3) NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"receivedBy" TEXT NOT NULL,CONSTRAINT "ReturnIntake_pkey" PRIMARY KEY ("id"));
