ALTER TABLE "ReturnIntake" ADD CONSTRAINT "ReturnIntake_returnId_fkey" FOREIGN KEY ("returnId") REFERENCES "CommercialReturn"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "AccountingNotice" ("id" TEXT NOT NULL,"returnId" TEXT NOT NULL,"reference" TEXT NOT NULL,"reason" TEXT NOT NULL,"requiresReconciliation" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" TEXT NOT NULL,CONSTRAINT "AccountingNotice_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AccountingNotice_returnId_key" ON "AccountingNotice"("returnId");
CREATE UNIQUE INDEX "AccountingNotice_reference_key" ON "AccountingNotice"("reference");
